export class BatchesComponent {
  api = inject(ApiService);
  batches = [];
  allStudents = [];
  plans = [];
  faculty = [];
  showModal = false;
  editingBatch = null;
  loading = false;
  errorMessage = '';
  batchTab = 'basic';
  batchForm = {
    name: '',
    description: '',
    planId: null,
    startDate: '',
    endDate: '',
    isActive: true,
    maxStudents: null,
    schedule: '',
    mentorId: null
  };
  // Batch detail / manage students
  showBatchDetail = false;
  selectedBatch = null;
  batchStudents = [];
  showAddStudent = false;
  selectedStudentId = null;
  ngOnInit() {
    this.loadBatches();
    this.loadStudents();
    this.loadPlans();
    this.loadFaculty();
  }
  loadFaculty() {
    this.api.get('/api/faculty').subscribe({
      next: data => {
        this.faculty = data;
      },
      error: err => {
        console.error('Failed to load faculty', err);
        this.faculty = [];
      }
    });
  }
  getMentorName(mentorId) {
    if (!mentorId) return '';
    const f = this.faculty.find(x => x.id === mentorId);
    return f ? f.name : '';
  }
  loadBatches() {
    this.api.get('/api/batches').subscribe({
      next: data => {
        this.batches = data;
      },
      error: err => {
        console.error('Failed to load batches', err);
        this.batches = [];
      }
    });
  }
  loadStudents() {
    this.api.get('/api/students').subscribe({
      next: data => {
        this.allStudents = data;
      },
      error: err => {
        console.error('Failed to load students', err);
        this.allStudents = [];
      }
    });
  }
  loadPlans() {
    this.api.get('/api/subscription-plans/admin/all').subscribe({
      next: data => {
        this.plans = data;
      },
      error: err => {
        console.error('Failed to load subscription plans', err);
        this.plans = [];
      }
    });
  }
  getPlanName(planId) {
    if (!planId) return '';
    const plan = this.plans.find(p => p.id === planId);
    return plan ? plan.name : '';
  }
  formatDate(date) {
    if (!date) return '-';
    try {
      return new Date(date).toLocaleDateString('en-IN', {
        day: '2-digit',
        month: 'short',
        year: 'numeric'
      });
    } catch {
      return date;
    }
  }
  getBatchStudentCount(batchId) {
    return this.allStudents.filter(s => s.batchId === batchId).length;
  }
  openAddModal() {
    this.editingBatch = null;
    this.errorMessage = '';
    this.batchTab = 'basic';
    this.batchForm = {
      name: '',
      description: '',
      planId: null,
      startDate: '',
      endDate: '',
      isActive: true,
      maxStudents: null,
      schedule: '',
      mentorId: null
    };
    this.showModal = true;
  }
  openEditModal(batch) {
    this.editingBatch = batch;
    this.errorMessage = '';
    this.batchTab = 'basic';
    this.batchForm = {
      name: batch.name,
      description: batch.description || '',
      planId: batch.planId || null,
      startDate: batch.startDate ? new Date(batch.startDate).toISOString().slice(0, 16) : '',
      endDate: batch.endDate ? new Date(batch.endDate).toISOString().slice(0, 16) : '',
      isActive: batch.isActive,
      maxStudents: batch.maxStudents || null,
      schedule: batch.schedule || '',
      mentorId: batch.mentorId || null
    };
    this.showModal = true;
  }
  closeModal(event) {
    this.showModal = false;
    this.editingBatch = null;
    this.errorMessage = '';
  }
  saveBatch() {
    if (!this.batchForm.name) {
      this.errorMessage = 'Batch name is required';
      return;
    }
    this.loading = true;
    this.errorMessage = '';
    const payload = {
      ...this.batchForm
    };
    if (this.editingBatch) {
      this.api.put(`/api/batches/${this.editingBatch.id}`, payload).subscribe({
        next: () => {
          this.loading = false;
          this.loadBatches();
          this.closeModal();
        },
        error: err => {
          this.loading = false;
          console.error('Failed to update batch', err);
          this.errorMessage = 'Failed to update batch. ' + (err.error?.message || 'Please check the details and try again.');
        }
      });
    } else {
      this.api.post('/api/batches', payload).subscribe({
        next: () => {
          this.loading = false;
          this.loadBatches();
          this.closeModal();
        },
        error: err => {
          this.loading = false;
          console.error('Failed to create batch', err);
          this.errorMessage = 'Failed to create batch. ' + (err.error?.message || 'Please check the details and try again.');
        }
      });
    }
  }
  deleteBatch(batch) {
    if (!confirm(`Are you sure you want to delete batch "${batch.name}"? Students will remain but will be unassigned from this batch.`)) return;
    this.api.delete(`/api/batches/${batch.id}`).subscribe({
      next: () => {
        this.loadBatches();
      },
      error: err => {
        console.error('Failed to delete batch', err);
        alert('Failed to delete batch');
      }
    });
  }
  // Batch detail / student management
  viewBatch(batch) {
    this.selectedBatch = batch;
    this.batchStudents = this.allStudents.filter(s => s.batchId === batch.id);
    this.showAddStudent = false;
    this.selectedStudentId = null;
    this.showBatchDetail = true;
  }
  closeBatchDetail(event) {
    this.showBatchDetail = false;
    this.selectedBatch = null;
    this.batchStudents = [];
    this.showAddStudent = false;
    this.selectedStudentId = null;
  }
  get availableStudents() {
    if (!this.selectedBatch) return [];
    return this.allStudents.filter(s => s.batchId !== this.selectedBatch.id);
  }
  addStudentToBatch() {
    if (!this.selectedBatch || !this.selectedStudentId) return;
    const student = this.allStudents.find(s => s.id === this.selectedStudentId);
    if (!student) return;
    const updatedStudent = {
      ...student,
      batchId: this.selectedBatch.id
    };
    this.api.put(`/api/students/${student.id}`, {
      name: student.name,
      email: student.email,
      phone: student.phone || '',
